package com.brainserve.onboarding.notifications.domain.model;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="notification_deliveries",schema="client_onboarding") public class NotificationDelivery {
@Id private UUID id;@Column(name="organization_id",nullable=false)private UUID organizationId;@Column(name="notification_id",nullable=false)private UUID notificationId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=16)private NotificationChannel channel;@Column(name="recipient_address",length=320)private String recipientAddress;@Enumerated(EnumType.STRING)@Column(nullable=false,length=24)private NotificationDeliveryStatus status;@Column(name="attempt_count",nullable=false)private int attemptCount;@Column(name="next_attempt_at",nullable=false)private Instant nextAttemptAt;@Column(name="sent_at")private Instant sentAt;@Column(name="delivered_at")private Instant deliveredAt;@Column(name="last_error",length=1000)private String lastError;@Column(name="provider_message_id",length=240)private String providerMessageId;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected NotificationDelivery(){}
public NotificationDelivery(UUID id,UUID org,UUID notificationId,NotificationChannel channel,String address,NotificationDeliveryStatus status,Instant now){this.id=id;this.organizationId=org;this.notificationId=notificationId;this.channel=channel;this.recipientAddress=address;this.status=status;this.attemptCount=0;this.nextAttemptAt=now;this.createdAt=now;this.updatedAt=now;if(status==NotificationDeliveryStatus.DELIVERED)this.deliveredAt=now;}
public void processing(Instant now){status=NotificationDeliveryStatus.PROCESSING;attemptCount++;nextAttemptAt=now.plusSeconds(600);updatedAt=now;}public void sent(Instant now){status=NotificationDeliveryStatus.SENT;sentAt=now;deliveredAt=now;updatedAt=now;lastError=null;}public void failed(String error,Instant next,boolean dead,Instant now){status=dead?NotificationDeliveryStatus.DEAD:NotificationDeliveryStatus.FAILED;lastError=error==null?"Delivery failed":error.substring(0,Math.min(error.length(),1000));nextAttemptAt=next;updatedAt=now;}
public UUID getId(){return id;}public UUID getOrganizationId(){return organizationId;}public UUID getNotificationId(){return notificationId;}public NotificationChannel getChannel(){return channel;}public String getRecipientAddress(){return recipientAddress;}public NotificationDeliveryStatus getStatus(){return status;}public int getAttemptCount(){return attemptCount;}public Instant getNextAttemptAt(){return nextAttemptAt;}public Instant getSentAt(){return sentAt;}public Instant getDeliveredAt(){return deliveredAt;}public String getLastError(){return lastError;}public Instant getCreatedAt(){return createdAt;}
}
